-- Keep the generated resource records aligned with the encyclopedia order in
-- game_settings.lua: KR1 -> Rebborn2 -> Rebborn1 -> KR5.  The KR4 block still
-- begins at index 318, so only the three blocks before it need reindexing.
for _, enemy in pairs(data.enemies) do
	if enemy.generation == 5 and enemy.encyclopedia_index >= 172 and enemy.encyclopedia_index <= 300 then
		enemy.encyclopedia_index = enemy.encyclopedia_index + 17
	end
end

local imported_encyclopedia_order = {
	"enemy_fremen",
	"enemy_sand_monk",
	"enemy_umbral_acolyte",
	"enemy_primordial",
	"enemy_set",
	"eb_malagar",
	"enemy_hobgoblin_small",
	"enemy_cursed_shaman",
	"enemy_hobgoblin_shield",
	"enemy_hobgoblin_rider",
	"enemy_goblin_spear",
	"enemy_goblin_balloon",
	"enemy_cursed_golem",
	"enemy_cursed_shard",
	"enemy_hobgoblin_miniboss",
	"eb_hobgoblin",
	"enemy_goblin_platform",
}

for i, name in ipairs(imported_encyclopedia_order) do
	data.enemies[name].encyclopedia_index = 171 + i
end

local main_segment_ranges = {
	g1_main = {{45, 50, "g1_main_01"}, {51, 53, "g1_main_02"}, {54, 56, "g1_main_03"}},
	g2_main = {{23, 28, "g2_main_01"}, {29, 33, "g2_main_02"}, {34, 37, "g2_main_03"}},
	g3_main = {{1, 6, "g3_main_01"}, {7, 11, "g3_main_02"}, {12, 15, "g3_main_03"}},
	g4_main = {{150, 156, "g4_main_01"}, {157, 161, "g4_main_02"}, {162, 166, "g4_main_03"}},
	g5_main = {{101, 106, "g5_main_01"}, {107, 111, "g5_main_02"}, {112, 116, "g5_main_03"}},
}

for _, enemy in pairs(data.enemies) do
	local source_region = enemy.region
	local ranges = main_segment_ranges[source_region]

	if ranges and enemy.first_level then
		for _, range in ipairs(ranges) do
			if enemy.first_level >= range[1] and enemy.first_level <= range[2] then
				enemy.region = range[3]
				if enemy.context == source_region then
					enemy.context = range[3]
				end
				break
			end
		end
	end
end

local normal_texture_exceptions = {
	enemy_werewolf_db = true,
	enemy_kr4_screecher_bat = true,
}

local scaled_texture_exceptions = {
	enemy_tower_ray_sheep = true,
	enemy_pumpkin_witch = true,
}

local scaled_texture_count = 0

for name, enemy in pairs(data.enemies) do
	-- KR4 atlases use scale_required_textures except for the two Halloween
	-- enemies that deliberately reuse a KR1-sized common atlas. KR5 terrain 9
	-- and the two atlas-only spawn templates use the same scaled load path.
	enemy.scale_required_texture = (enemy.generation == 4 and not normal_texture_exceptions[name])
		or enemy.region == "g5_branch_06"
		or scaled_texture_exceptions[name]
		or false

	if enemy.scale_required_texture then
		scaled_texture_count = scaled_texture_count + 1
	end
end

data.statistics.scale_required_texture_entries = scaled_texture_count

return data
